import {useMutation, useSuspenseQuery} from "@tanstack/react-query";

import {EntryList} from "./-local/entry-list";
import {fetchEntries, postEntry} from "./entry-api";

/** @summary 엔트리 목록 화면을 렌더링한다. */
export const EntriesPage = () => {
  const entryResponse = useSuspenseQuery({queryKey: ["entries"], queryFn: fetchEntries});
  const entryMutation = useMutation({mutationFn: postEntry});
  const entries = entryResponse.data.entries;
  const items = entries.map((entry) => ({id: entry.id, label: entry.title.trim()}));
  const meta = {total: entryResponse.data.total};

  return <EntryList items={items} total={meta.total} onCreate={entryMutation.mutate} />;
};

