/** @summary 엔트리 생성 payload 계약이다. */
interface CreateEntryPayload {
  /** @field 엔트리 식별자 */
  entryId: string;
  /** @field 표시 이름 */
  name: string;
  /** @field 분류 태그 */
  tags: string[];
  /** @field 활성 여부 */
  enabled: boolean;
}

/** @helper 입력값을 엔트리 생성 payload로 정규화한다. */
export const createEntryPayload = (
  entryId: string,
  name: string,
  tags: string[],
  enabled: boolean,
): CreateEntryPayload => ({entryId, name: name.trim(), tags, enabled});

