import type {MouseEventHandler} from "react";
import {useEffect, useState} from "react";

interface Entry {
  id: string;
  label: string;
}

/** @summary 엔트리 선택 화면을 렌더링한다. */
export const EntriesPage = ({entries}: {entries: Entry[]}) => {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [selectedCount, setSelectedCount] = useState(0);
  const [hasSelection, setHasSelection] = useState(false);

  useEffect(() => {
    setSelectedCount(selectedIds.length);
    setHasSelection(selectedIds.length > 0);
  }, [selectedIds]);

  /** @event 선택한 엔트리 식별자를 토글한다. */
  const handleSelectionToggle =
    (entryId: string): MouseEventHandler<HTMLButtonElement> =>
    (_event) => {
      setSelectedIds((previousSelectedIds) =>
        previousSelectedIds.includes(entryId)
          ? previousSelectedIds.filter((selectedId) => selectedId !== entryId)
          : [...previousSelectedIds, entryId],
      );
    };

  return (
    <section>
      <p>{hasSelection ? `${selectedCount} selected` : "No selection"}</p>
      {entries.map((entry) => (
        <button key={entry.id} onClick={handleSelectionToggle(entry.id)}>
          {entry.label}
        </button>
      ))}
    </section>
  );
};
